diff --git a/src/log.ts b/src/log.ts
index 4892c8b..e0430e4 100644
--- a/src/log.ts
+++ b/src/log.ts
@@ -1,3 +1,22 @@
+let buffer: string[] = [];
+let scheduled = false;
+
+const flush = (): void => {
+  if (buffer.length === 0) return;
+  const lines = buffer.join('');
+  buffer = [];
+  scheduled = false;
+  process.stdout.write(lines);
+};
+
+const schedule = (): void => {
+  if (!scheduled) {
+    scheduled = true;
+    setImmediate(flush);
+  }
+};
+
 export const log = (message: string): void => {
-  process.stdout.write(`${JSON.stringify({ message })}\n`);
+  buffer.push(`${JSON.stringify({ message })}\n`);
+  schedule();
 };
